const qmLanguages={'en':'English','zh-CN':'简体中文','es':'Español','fr':'Français','de':'Deutsch','ja':'日本語','ko':'한국어','id':'Bahasa Indonesia'};
function languageRoute(){let path=location.pathname.endsWith('/')?location.pathname:location.pathname+'/';const parts=path.split('/').filter(Boolean);const current=parts[0] in qmLanguages&&parts[0]!=='en'?parts.shift():'en';let base='/'+parts.join('/')+(parts.length?'/':'');if(base==='/products/quickmind-home/')base='/home-product/';return {current,base}}
function updateLanguageLinks(){const {current,base}=languageRoute();const selector=document.querySelector('[data-language-select]');if(selector)selector.value=current;const origin=location.origin;document.querySelectorAll('link[hreflang]').forEach(el=>el.remove());for(const [lang] of Object.entries(qmLanguages)){const link=document.createElement('link');link.rel='alternate';link.hreflang=lang;link.href=origin+(lang==='en'?'':'/'+lang)+base;document.head.appendChild(link)}const def=document.createElement('link');def.rel='alternate';def.hreflang='x-default';def.href=origin+base;document.head.appendChild(def)}
document.addEventListener('change',e=>{if(!e.target.matches('[data-language-select]'))return;const lang=e.target.value;if(!(lang in qmLanguages))return;try{const prefs=JSON.parse(localStorage.getItem('qm-preferences-v1')||'{}');prefs.language=lang;prefs.manualLanguage=true;localStorage.setItem('qm-preferences-v1',JSON.stringify(prefs))}catch{}const {base}=languageRoute();location.assign((lang==='en'?'':'/'+lang)+base+location.search+location.hash)});
document.addEventListener('DOMContentLoaded',updateLanguageLinks);
